#include <bits/stdc++.h>
using namespace std;
static const int MOD = 998244353;

int n;
vector<vector<int>> pos;

inline bool valid(int x, int y, int v, bool goLeft){
    int q= goLeft ? x+1 : n-y;
    int q2 = n+1 -q;
    
    for(int i : pos[v]){
        bool pre = false;
        if(i>=q){
            int c= min(x,i) + max(0, i-(n-y));
            pre = (c== (i+1)/2 - 1);
        }
        
        bool suf = false;
        int s=n+1-i;
        if(s>=q2){
            int c = min(y,s) + max(0, s-(n-x));
            suf = (c==(s+1)/2 - 1);
        }
        if(!pre && !suf) return false;
    }
    return true;
}

int main() {
	int t;
	cin>>t;
	while(t--){
	    cin>>n;
	    pos.assign(n+1, {});
	    
	    for(int i =1; i<=n; i++){
	        int a;
	        cin>>a;
	        pos[a].push_back(i);
	    }
	    
	    vector<int> curr(n+2,0);
	    vector<int> next(n+2,0);
	    
	    curr[0] = 1;
	    
	    for(int v=1; v<=n;v++){
	        fill(next.begin(), next.begin() + v +1, 0);
	        
	        for(int x=0; x<v;x++){
	            int w = curr[x];
	            if(!w) continue;
	            
	            int y = v-1-x;
	            
	            if(valid(x,y,v , true)){
	                next[x+1] += w;
	                if(next[x+1]>=MOD) next[x+1] -= MOD;
	            }
	            
	            if(v<n && valid(x,y,v,false)){
	                next[x] += w;
	                if(next[x] >= MOD) next[x] -= MOD;
	            }
	        }
	        swap(curr,next);
	    }
	    long long ans =0;
	    for(int  x=0; x<=n;x++){
	        ans+=curr[x];
	    }
	    cout<< ans%MOD << endl;
	}

}
